<?php $adminView=$adminView??false; $asset_prefix=$asset_prefix??''; function resume_bullets($text,$splitComma=false){ $items=preg_split('/\r\n|\r|\n/',trim((string)$text)); $out=[]; foreach($items as $item){ $item=trim($item); $item=preg_replace('/^[•\-–—*]+\s*/u','',$item); if($splitComma && strpos($item,',')!==false) $items2=explode(',',$item); else $items2=[$item]; foreach($items2 as $v){ $v=trim($v); if($v!=='') $out[]=$v; } } if(!$out)return ''; $html='<ul class="resume-bullets">'; foreach($out as $v)$html.='<li>'.e($v).'</li>'; return $html.'</ul>'; } $back=$adminView ? admin_tab_url('dashboard.php') : tab_url('builder.php'); $r['region']=$r['region']??'india'; $r['accent']=allowed_color($r['accent']??'#d97706'); $fontFamily=$r['font_family']??'DM Sans'; $fontSize=(float)($r['font_size']??10.5); $sidebarFontSize=(float)($r['sidebar_font_size']??$fontSize); $mainFontSize=(float)($r['main_font_size']??$fontSize); $fontWeight=$r['font_weight']??'400';  ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?php echo e($r['full_name']?:'Resume'); ?> — Preview</title><link rel="stylesheet" href="<?php echo e($asset_prefix); ?>assets/css/app.css"></head><body class="print-page"><div class="print-actions no-print"><a class="ghost" href="<?php echo $back; ?>">← Back</a><button class="primary" onclick="window.print()">Print / Save PDF</button></div><main class="resume-sheet final <?php echo e($r['layout']); ?> region-<?php echo e($r['region']); ?>" style="--accent:<?php echo e($r['accent']); ?>;--resume-font:<?php echo e($fontFamily); ?>;--resume-size:<?php echo e($fontSize); ?>pt;--resume-weight:<?php echo e($fontWeight); ?>;--sidebar-size:<?php echo e($sidebarFontSize); ?>pt;--main-size:<?php echo e($mainFontSize); ?>pt">
<?php if($r['layout']==='split'): ?><aside class="resume-side"><div class="photo-wrap"><?php if($r['photo']): ?><img src="<?php echo e($asset_prefix.$r['photo']); ?>" alt="Profile photo"><?php else: ?><div class="photo-placeholder"><?php echo e(strtoupper(substr($r['full_name']?:'Y',0,1))); ?></div><?php endif; ?></div><section><h4>CONTACT</h4><?php $contact=[$r['email'],$r['phone'],$r['location'],$r['address']]; ?><ul class="resume-bullets"><?php foreach($contact as $item): if(trim($item)): ?><li><?php echo e($item); ?></li><?php endif; endforeach; ?></ul></section><section><h4>SKILLS</h4><?php echo resume_bullets($r['skills'],true); ?></section><section><h4>LANGUAGES</h4><?php echo resume_bullets($r['languages'],false); ?></section><section><h4>HOBBIES</h4><?php echo resume_bullets($r['hobbies'],false); ?></section></aside><article class="resume-main"><header class="resume-header split-header"><div><h1><?php echo e($r['full_name']); ?></h1><p><?php echo e($r['headline']); ?></p><span><?php echo e($r['target_job']); ?></span></div></header><section class="resume-section split-profile"><h2>PROFILE</h2><div class="resume-text"><?php echo resume_bullets($r['career_objective'],false); ?></div></section><?php else: ?><article class="resume-main"><header class="resume-header"><div><?php if($r['photo']): ?><img class="header-photo" src="<?php echo e($asset_prefix.$r['photo']); ?>"><?php endif; ?><h1><?php echo e($r['full_name']); ?></h1><p><?php echo e($r['headline']); ?></p><span><?php echo e($r['email']); ?> · <?php echo e($r['phone']); ?> · <?php echo e($r['location']); ?></span></div></header><?php endif; ?>
<?php $sections=[['EXPERIENCE','experience'],['PROJECTS','projects'],['ACADEMIC QUALIFICATION','academic_qualification'],['CERTIFICATIONS','certifications'],['ACHIEVEMENTS','achievements'],['SKILLS','skills'],['LANGUAGES','languages'],['HOBBIES','hobbies']]; foreach($sections as $sec): if(trim($r[$sec[1]]??'') && $r['layout']!=='split' || trim($r[$sec[1]]??'') && $r['layout']==='split' && !in_array($sec[1],['skills','languages','hobbies'],true)): ?><section class="resume-section"><h2><?php echo $sec[0]; ?></h2><div class="resume-text"><?php if(in_array($sec[1],['career_objective','experience','projects','skills','languages','hobbies'],true)) echo resume_bullets($r[$sec[1]],$sec[1]==='skills'); else echo nl2br(e($r[$sec[1]])); ?></div></section><?php endif; endforeach; ?><div class="resume-links"><?php foreach(['linkedin'=>'LinkedIn','github'=>'GitHub','portfolio'=>'Portfolio'] as $l=>$label): if(trim($r[$l]??'')): $u=trim($r[$l]); if(!preg_match('~^https?://~i',$u)) $u='https://'.$u; ?><a class="resume-link" href="<?php echo e($u); ?>" target="_blank" rel="noopener noreferrer"><strong><?php echo e($label); ?>:</strong> <span><?php echo e(preg_replace('/[?#].*$/','',$u)); ?></span></a><?php endif; endforeach; ?></div></article></main><?php if($adminView): ?><script src="<?php echo e($asset_prefix); ?>assets/js/admin-tab-auth.js"></script><?php else: ?><script src="<?php echo e($asset_prefix); ?>assets/js/tab-auth.js"></script><?php endif; ?></body></html>
